func (self *TargetCGI)Unpack(stream *Stream) {
    //coptions := []string{"nr","e-utra","choice-extension","Unknown"}
    choice := stream.get_choice(2, 0, 3)
    if choice == 0 { //ch1
        self.Nr = &NRCGI{}//cho6
        self.Nr.Unpack(stream)
    } else if choice == 1 { //ch2
        self.Eutra = &EUTRACGI{}//cho6
        self.Eutra.Unpack(stream)
    } else if choice == 2 { //ch2
        Choiceextension := &ProtocolIESingleContainer{}//cho2
        self.Choiceextension = &TargetCGIExtIEs{}//cho3
        Choiceextension.Unpack(stream, self.Choiceextension)
    }//end of if else

}
func (self * TargetCGI) Pack(stream *Stream) {
    if self.Nr != nil {
        stream.set_choice(0, 2, 0, 3)
        self.Nr.Pack(stream)//2
    } else if self.Eutra != nil {
        stream.set_choice(1, 2, 0, 3)
        self.Eutra.Pack(stream)//2
    } else if self.Choiceextension != nil {
        stream.set_choice(2, 2, 0, 3)
        Choiceextension := ProtocolIESingleContainer{}//cho2
        Choiceextension.Pack(stream, self.Choiceextension)
    }

}
